/** Inactive prefix probe: stop before leaf/full scoring, prohibit every engine action. */
import assert from "node:assert/strict";
import {SearchDriver} from "./sources/common/src/simulation/search_driver";
import {captureDeterministicRandomState} from "./sources/common/src/utils/lib";
import {normalize} from "./normalize";
const nativeChoose=SearchDriver.prototype.chooseDecision;
const hashState=(driver:any)=>normalize(Object.fromEntries(Object.getOwnPropertyNames(driver)
 .filter(k=>k!=="deps"&&k!=="match"&&typeof driver[k]!=="function").map(k=>[k,driver[k]])));
export function compileCatalog(driver:any,unit:any,incumbent:any[],context:any){
 const beforeDriver=hashState(driver),random=captureDeterministicRandomState(),active=driver.deps.getActiveUnitId();
 const stop={catalogReady:true},forbidden={forbiddenPrefixOperation:true};
 let catalog:any[]|undefined,error:unknown,engineApplyAttempts=0,rolloutAttempts=0,scoreAttempts=0;
 const shadow:any=Object.create(SearchDriver.prototype),objects:any[]=[];
 try{
  for(const key of Object.getOwnPropertyNames(driver)){
   if(key==="deps"||key==="match"||typeof driver[key]==="function")continue;
   const value=driver[key];shadow[key]=structuredClone(value);
   if(value!==null&&typeof value==="object")objects.push({key,prototype:value.constructor?.name??null});
  }
  shadow.match={...driver.match,offlineDeterministicWork:true};
  shadow.deps={...driver.deps,engine:new Proxy(driver.deps.engine,{get(target,key,receiver){
   if(key==="apply")return()=>{engineApplyAttempts++;throw forbidden;};return Reflect.get(target,key,receiver);
  }})};
  shadow.search=function(_u:any,candidates:any[]){catalog=structuredClone(candidates);throw stop;};
  shadow.rollout=()=>{rolloutAttempts++;throw forbidden;};
  shadow.scoreCandidates=()=>{scoreAttempts++;throw forbidden;};
  // A fresh public context must not consume the caller's once-only shared path facade.
  const{decisionPathCatalog:unused,...plain}=context??{};
  nativeChoose.call(shadow,unit,"v0.8",incumbent,{...plain,decisionOrigin:"root"});
 }catch(caught){if(caught!==stop)error=caught;}
 finally{
  assert.deepEqual(captureDeterministicRandomState(),random,"Catalog prefix changed the RNG/UUID source or counter");
  assert.equal(driver.deps.getActiveUnitId(),active,"Catalog prefix changed active unit");
  assert.deepEqual(hashState(driver),beforeDriver,"Catalog prefix changed the owning SearchDriver");
 }
 return{status:catalog&&!error&&!engineApplyAttempts&&!rolloutAttempts&&!scoreAttempts?"catalog-ready":"unavailable",
  candidates:catalog??[],error:error===forbidden?"forbidden-prefix-operation":error?String(error):catalog?null:"returned-before-search",
  engineApplyAttempts,rolloutAttempts,scoreAttempts,clonedOwnerObjectFields:objects};
}

/** Passive reused-v11 recording only. No policy, rollout, candidate or model change. */
import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {appendFileSync,statSync,mkdirSync} from "node:fs";
import {dirname,basename,join} from "node:path";
import {compileCatalog} from "./catalog";
import {project,actionKey} from "./representation";
import {createInterface} from "node:readline";
import {gzipSync} from "node:zlib";
import {buildChoice} from "./build-choice";
import {fightNative,hash} from "./native-audit";
import {normalize} from "./normalize";
import {selectBarrelForecastIntent} from "./sources/common/src/simulation/barrel_forecast_intent_research";
import {canWaitOnHourglass,hasActiveTimeDenial} from "./sources/common/src/engine/hourglass";
import {SearchDriver} from "./sources/common/src/simulation/search_driver";
import {snapshotBattle} from "./sources/common/src/simulation/battle_snapshot";
import {captureDeterministicRandomState} from "./sources/common/src/utils/lib";
import {permuteRankedDraftSeed} from "./sources/common/src/simulation/ranked_draft_eval";
import {V08_A19_PROFILE_SCHEMA} from "./sources/common/src/ai/versions/v0_8_a19_profile";
import {environment} from "./profiles";
const [output,labelOutput,stateOutput,mode]=process.argv.slice(2),g=globalThis as any;
assert(["baseline","observe"].includes(mode));assert.equal(V08_A19_PROFILE_SCHEMA,"hoc.v0_8_a19_production_profile.v11");
assert.equal(environment.SEARCH_ROLLOUTS,"2");assert.equal(environment.SEARCH_HORIZON,"64");
let collecting=false,fault:string|undefined,turns=0,pending:any[]=[],labels:any[]=[],rootRecords:any[]=[];
let activeRoot:any,activeQuery:any,rolloutOwner:any;
let catalogProbes:any[]=[],hypotheticalEligibleCalls=0,rootProbeMap=new WeakMap<object,any>();
const probeOutput=join(dirname(output),"probes",basename(output).replace(/\.jsonl\.gz$/,"-catalogs.jsonl.gz"));
mkdirSync(dirname(probeOutput),{recursive:true});
let live:any,frames:any[]=[],snapshots:any[]=[],snapshotKeys:Set<string>,unitRefs:WeakMap<object,number>,nextUnitRef=0;
let turnHash:ReturnType<typeof createHash>,eventHash:ReturnType<typeof createHash>;
const proto=SearchDriver.prototype as any,choose=proto.chooseDecision,shortlist=proto.shortlistCandidates,score=proto.scoreCandidates,rollout=proto.rollout;
const clone=(x:any)=>structuredClone(x);
const candidates=(xs:any[])=>xs.map(x=>clone(x));
const observing=()=>collecting&&mode==="observe";
function fail(error:unknown){fault=String(error);throw error;}
proto.chooseDecision=function(unit:any,version:any,incumbent:any,context:any){
    if(collecting){
        assert.equal(this.barrelForecastMixture,false);assert.equal(this.liveCertifiedBounds,false);
        assert.equal(this.scoredDecisionObserver,undefined);assert.equal(this.passiveProductiveProbeObserver,undefined);
    }
    if(!observing()||!pending.some(p=>p.actualTurn===turns&&p.unitId===unit.getId()))return choose.call(this,unit,version,incumbent,context);
    const previous=activeRoot;
    const record={actualTurn:turns,unitId:unit.getId(),version,rawIncumbent:clone(incumbent),shortlists:[] as any[],queries:[] as any[],innerChosen:undefined as any};
    const observed=pending.find(p=>p.actualTurn===turns&&p.unitId===unit.getId());
    const probe=observeCatalog(this,unit,context,incumbent,observed.before,"root",observed.publicState);
    rootProbeMap.set(record,probe);
    activeRoot=record;rootRecords.push(record);
    try{const selected=choose.call(this,unit,version,incumbent,context);record.innerChosen=clone(selected);return selected;}
    catch(error){return fail(error);}
    finally{activeRoot=previous;}
};
proto.shortlistCandidates=function(unit:any,xs:any[],...args:any[]){
    if(!observing()||!activeRoot)return shortlist.call(this,unit,xs,...args);
    try{
        const input=candidates(xs);
        if(activeRoot.shortlists.length===0){
            const probe=rootProbeMap.get(activeRoot);assert(probe);
            probe.actualCatalogSha256=hash(input);probe.completeCatalogMatches=probe.catalogSha256===hash(input);
            probe.orderedActionKeysMatch=hash(probe.compiled.candidates.map((c:any)=>actionKey(c.actions)))===hash(input.map((c:any)=>actionKey(c.actions)));
            const observed=pending.find(p=>p.actualTurn===turns&&p.unitId===unit.getId());
            const actual=project({actorId:unit.getId(),lap:observed.lap,publicState:observed.publicState,before:observed.before,cleanup:activeRoot.rawIncumbent,nativeCatalog:input});
            probe.featureRowsMatch=hash(actual.map(p=>p.features))===probe.featureRowsSha256;
        }
        const selected=shortlist.call(this,unit,xs,...args);
        activeRoot.shortlists.push({input,output:candidates(selected),unitId:unit.getId()});return selected;
    }catch(error){return fail(error);}
};
proto.scoreCandidates=function(unit:any,xs:any[],...args:any[]){
    if(!observing()||!activeRoot)return score.call(this,unit,xs,...args);
    const prior=activeQuery;
    const q={unitId:unit.getId(),mode:args[1],rollouts:args[2]??this.rollouts,turnHorizon:args[4]??this.horizon,
        // Seeds are replay metadata only; projected values and action results are labels/diagnostics.
        seedBase:args[0],candidates:candidates(xs),samples:[] as any[],scores:[] as any[],indices:new Map(xs.map((c,i)=>[c,i]))};
    activeQuery=q;
    try{
        const result=score.call(this,unit,xs,...args);
        q.scores=result.map((v:number)=>({value:Number.isFinite(v)?v:null,tag:Number.isFinite(v)?"finite":String(v)}));
        const {indices,...detached}=q;activeRoot.queries.push(detached);return result;
    }catch(error){return fail(error);}
    finally{activeQuery=prior;}
};
proto.rollout=function(unit:any,candidate:any,...args:any[]){
    const previousOwner=rolloutOwner;rolloutOwner=this;
    try{
    if(!observing()||!activeRoot||!activeQuery)return rollout.call(this,unit,candidate,...args);
    assert(activeQuery.indices.has(candidate));
    const query=activeQuery,index=query.indices.get(candidate),engine=this.deps.engine;
    const descriptor=Object.getOwnPropertyDescriptor(engine,"apply"),apply=engine.apply,attempts:any[]=[];
    let nextRootAction=0,value:number|undefined;
    Object.defineProperty(engine,"apply",{configurable:true,writable:true,value:function(action:any){
        const rootAction=nextRootAction<candidate.actions.length&&action===candidate.actions[nextRootAction];
        const data=rootAction?clone(action):undefined;if(rootAction)nextRootAction++;
        const result=apply.call(this,action);
        if(rootAction)attempts.push({action:data,completed:result.completed,rejectionReason:result.rejectionReason});
        return result;
    }});
    try{value=rollout.call(this,unit,candidate,...args);return value;}
    catch(error){return fail(error);}
    finally{
        if(descriptor)Object.defineProperty(engine,"apply",descriptor);else Reflect.deleteProperty(engine,"apply");
        query.samples.push({candidateIndex:index,sampleIndex:args[1],mode:args[2],attempts,
            score:value!==undefined&&Number.isFinite(value)?value:null,
            scoreTag:value===undefined?"thrown":Number.isFinite(value)?"finite":String(value)});
    }
    }finally{rolloutOwner=previousOwner;}
};
function publicUnit(u:any,fp:any,all:any){
    return {id:u.getId(),name:u.getName(),team:u.getTeam(),cells:clone(u.getCells()),hp:u.getCumulativeHp(),alive:u.getAmountAlive(),
        maxHp:u.getMaxHp(),exp:u.getExp(),steps:u.getSteps(),initiative:u.getInitiative(),armor:u.getArmor(),rangeArmor:u.getRangeArmor(),
        shots:u.getRangeShots(),fly:u.canFly(),dead:u.isDead(),attackSelection:u.getAttackTypeSelection(),properties:clone(u.getUnitProperties()),
        spells:u.getSpells().map((s:any)=>({name:s.getName(),remaining:s.getAmount(),properties:s.getSpellProperties()})),
        turnLegality:{hasMoved:u.hasMovedThisTurn(),isOnHourglass:u.isOnHourglass(),hourglassIncludes:fp.hourglassIncludes(u.getId()),
            alreadyMadeTurn:fp.hasAlreadyMadeTurn(u.getId()),alreadyHourglass:fp.hasAlreadyHourglass(u.getId()),
            activeTimeDenial:u.hasAbilityActive("Time Denial"),
            hasUnactedTeammate:fp.hasUnactedTeammate(u.getTeam(),u.getId(),all),canWait:canWaitOnHourglass(u,fp,all)}};
}
function publicState(unit:any,context:any){
 const all=context.unitsHolder.getAllUnits(),fp=context.fightProperties;
 return{gridType:context.grid.getGridType(),matrix:clone(context.matrix),
  gridGeometry:{gridSize:context.grid.getSettings().getGridSize(),cellSize:context.grid.getSettings().getCellSize(),maxX:context.grid.getSettings().getMaxX()},
  units:[...all.values()].map((u:any)=>publicUnit(u,fp,all)),activeTimeDenial:hasActiveTimeDenial(all.values()),
  barrels:clone(context.grid.getArtifactBarrels()),terrain:clone(context.grid.getScatteredMountainsStanding()),upNext:[...fp.getUpNextQueueIterable()]};
}
function probeState(owner:any,context:any){
 const snap=snapshotBattle(context.unitsHolder,context.grid,context.fightProperties),{unitRefs:ignored,...data}=snap;
 return normalize({battle:data,activeUnitId:owner.deps.getActiveUnitId(),uuidSequence:captureDeterministicRandomState().uuidSequence,
  actualRandomDraws:g.__auditRng.count,actualRandomPrefix:g.__auditRng.hash.copy().digest("hex")});
}
function observeCatalog(owner:any,unit:any,context:any,cleanup:any[],before:any[],origin:string,state:any){
 const refs=[...context.unitsHolder.getAllUnits()],originals=refs.map(([id,u]:any)=>[id,u]);
 const beforeState=probeState(owner,context),compiled=compileCatalog(owner,unit,cleanup,context),afterState=probeState(owner,context);
 assert.deepEqual(afterState,beforeState,"Catalog probe changed the mutable battle");
 for(const[id,u]of originals)assert.equal(context.unitsHolder.getAllUnits().get(id),u,"Catalog probe replaced a live unit");
 const featureRows=compiled.status==="catalog-ready"?project({actorId:unit.getId(),lap:context.fightProperties.getCurrentLap(),publicState:state,before,cleanup,nativeCatalog:compiled.candidates}):[];
 const probe={ordinal:catalogProbes.length,origin,actualTurn:turns,hypotheticalEligibleCall:origin==="rollout"?hypotheticalEligibleCalls:null,
  unitId:unit.getId(),actor:unit.getName(),team:unit.getTeam(),lap:context.fightProperties.getCurrentLap(),compiled,
  input:{actorId:unit.getId(),lap:context.fightProperties.getCurrentLap(),publicState:state,before:clone(before),cleanup:clone(cleanup)},
  catalogSha256:hash(compiled.candidates),featureRows:featureRows.map(p=>({key:p.key,features:p.features,blockedByPublicMask:p.blockedByPublicMask})),
  featureRowsSha256:hash(featureRows.map(p=>p.features)),beforeState,afterState,beforeStateSha256:hash(beforeState),afterStateSha256:hash(afterState),allUnitReferencesSame:true};
 catalogProbes.push(probe);return probe;
}
g.__catalogReplayBoundary=(unit:any,context:any,before:any[],cleanup:any[])=>{
 if(!collecting||context.decisionOrigin!=="rollout")return;
 if(selectBarrelForecastIntent(unit,{...context,decisionOrigin:"rollout"},before,cleanup)===cleanup)return;
 hypotheticalEligibleCalls++;
 if(!observing()||hypotheticalEligibleCalls>32)return;
 assert(rolloutOwner,"Eligible hypothetical boundary needs its actual owning driver");
 observeCatalog(rolloutOwner,unit,context,cleanup,before,"rollout",publicState(unit,context));
};

g.__barrelLegalRootObservation=(unit:any,context:any,before:any[],cleanup:any[])=>{
    if(!observing()||context.decisionOrigin!=="root")return cleanup;
    try{
        if(selectBarrelForecastIntent(unit,{...context,decisionOrigin:"rollout"},before,cleanup)===cleanup)return cleanup;
        const all=context.unitsHolder.getAllUnits(),fp=context.fightProperties;
        pending.push({actualTurn:turns,unitId:unit.getId(),actor:unit.getName(),team:unit.getTeam(),lap:fp.getCurrentLap(),
            before:clone(before),cleanup:clone(cleanup),publicState:{gridType:context.grid.getGridType(),matrix:clone(context.matrix),
                gridGeometry:{gridSize:context.grid.getSettings().getGridSize(),cellSize:context.grid.getSettings().getCellSize(),maxX:context.grid.getSettings().getMaxX()},
                units:[...all.values()].map((u:any)=>publicUnit(u,fp,all)),activeTimeDenial:hasActiveTimeDenial(all.values()),
                barrels:clone(context.grid.getArtifactBarrels()),terrain:clone(context.grid.getScatteredMountainsStanding()),upNext:[...fp.getUpNextQueueIterable()]}});
    }catch(error){return fail(error);}
    return cleanup;
};
function capture(turn:any|null){
    const snap=snapshotBattle(live.unitsHolder,live.grid,live.fightProperties),{unitRefs:refs,...data}=snap;
    const references=[...refs].map(([id,object])=>{
        let token=unitRefs.get(object);if(token===undefined){token=nextUnitRef++;unitRefs.set(object,token);}return[id,token,object.constructor.name];
    });
    const state=normalize(data),stateSha256=hash(state),random=captureDeterministicRandomState();
    frames.push({frame:frames.length,stateSha256,unitReferenceTokens:references,targetMemorySha256:hash([...snap.aiTargetMemory]),
        uuidSequence:random.uuidSequence,liveRandomDrawCount:g.__auditRng.count,liveRandomPrefixSha256:g.__auditRng.hash.copy().digest("hex"),
        actualTurnPrefixSha256:turnHash.copy().digest("hex"),eventPrefixSha256:eventHash.copy().digest("hex"),
        rawAndChosenShareArray:turn?turn.rawIncumbent===turn.chosenDecision:null});
    if(!snapshotKeys.has(stateSha256)){snapshotKeys.add(stateSha256);snapshots.push({stateSha256,state});}
}
g.__legalCommittedEvent=(r:any)=>eventHash.update(JSON.stringify(r));
g.__rushBeforeFight=(context:any)=>{live=context;capture(null);};
g.__rushTurn=(r:any)=>{
    turnHash.update(JSON.stringify(r));capture(r);
    if(observing())for(const observation of pending){
        assert.equal(observation.actualTurn,turns);assert.equal(observation.unitId,r.unitId);
        const actor=observation.publicState.units.find((u:any)=>u.id===r.unitId);assert(actor);
        for(const a of r.strategyActions)if(a.action.type==="wait_turn"&&a.completed)assert(actor.turnLegality.canWait,"Successful actual wait must be legal at the recorded root");
        const roots=rootRecords.filter(x=>x.actualTurn===turns&&x.unitId===r.unitId);
        labels.push({...observation,ordinal:labels.length,rootCallOrdinal:labels.filter(o=>o.actualTurn===turns).length,
            strategyVersion:r.strategyVersion,rootCatalogStatus:roots.length?"searched-root":"native-only-or-search-bypass",
            rootRecords:clone(roots),actualRawIncumbent:clone(r.rawIncumbent),chosenDecision:clone(r.chosenDecision),
            strategyActions:clone(r.strategyActions),recovery:clone(r.recovery),rawAndChosenShareArray:r.rawIncumbent===r.chosenDecision});
    }
    pending=[];rootRecords=[];turns++;
};
g.__mixtureDecisionCompleted=(o:any)=>assert.equal(o.context.a19BarrelIntentForecast,undefined);
function append(path:string,row:any){
    const raw=gzipSync(JSON.stringify(row)+"\n",{level:1});let size=0;try{size=statSync(path).size;}catch{}
    assert(size+raw.length<=128*1024*1024,"Fixed actor output ceiling; never truncate or retry");appendFileSync(path,raw);
}
for await(const line of createInterface({input:process.stdin})){
    const {job,registrationSha256}=JSON.parse(line);assert.equal(job.mode,mode);
    collecting=false;fault=undefined;turns=0;pending=[];labels=[];rootRecords=[];activeRoot=undefined;activeQuery=undefined;
    catalogProbes=[];hypotheticalEligibleCalls=0;rootProbeMap=new WeakMap();rolloutOwner=undefined;
    g.__mode="stock";g.__mixtureLiveMode=false;
    const team=(job.game<2)===(job.game%2===0)?2:1,combatSeed=permuteRankedDraftSeed(job.seed+6+Number(job.game>=2));
    const built=buildChoice(job,"current","current",team);
    assert.equal(hash(built.drafted.config),job.draftConfigSha256[Number(job.game>=2)]);
    const inputSha256=hash({config:built.opening.config,teams:built.opening.teams,terrain:built.opening.terrain,combatSeed});
    assert.equal(inputSha256,job.reference.inputSha256);
    frames=[];snapshots=[];snapshotKeys=new Set();unitRefs=new WeakMap();nextUnitRef=0;turnHash=createHash("sha256");eventHash=createHash("sha256");
    collecting=true;let fought:ReturnType<typeof fightNative>;
    try{fought=fightNative(clone(built.opening),combatSeed);}finally{collecting=false;}
    const score=fought.result.winner==="draw"?.5:Number(fought.result.winner===(team===2?"green":"red"));
    const statePayload={jobId:job.jobId,mode,snapshots};append(stateOutput,statePayload);
    const labelPayload={jobId:job.jobId,mode,labels};append(labelOutput,labelPayload);
    const catalogPayload={jobId:job.jobId,mode,hypotheticalEligibleCalls,probes:catalogProbes};append(probeOutput,catalogPayload);
    append(output,{...job,registrationSha256,catalogProbePayloadSha256:hash(catalogPayload),catalogProbes:catalogProbes.length,hypotheticalEligibleCalls,inputSha256,traceSha256:fought.traceSha256,score,winner:fought.result.winner,
        actualTurns:turns,frames,frameDigest:hash(frames),labels:labels.length,labelsDigest:hash(labels),labelPayloadSha256:hash(labelPayload),statePayloadSha256:hash(statePayload),quality:fought.quality,
        observationFault:fault??null,pendingUncommitted:clone(pending),rootRecordsUncommitted:clone(rootRecords),
        additionalRolloutsRequested:0,sourceProfile:"frozen-v11-harness-only",defaultChanged:false,modelFitted:false});
    // Emit every completed observation before a failed original control stops the single attempt.
    assert(!fault,`Observation error swallowed: ${fault}`);assert.equal(pending.length,0);assert.equal(rootRecords.length,0);
    assert.equal(fought.result.endReason,"elimination");
    assert.equal(fought.traceSha256,job.reference.traceSha256);assert.equal(score,job.reference.score);
    for(const n of fought.quality.neural)for(const k of["modelErrors","missingStart","deadlineAbstentions","inferenceOverruns"])assert.equal(n[k],0);
    for(const w of fought.quality.work)for(const k of["deadlineFallbacks","degradedDecisions","circuitSkipped","circuitWaitArbitrations"])assert.equal(w[k]??0,0);
    console.log(JSON.stringify({verified:true,jobId:job.jobId,rows:1,labels:labels.length}));
}

/** Inactive public-input prototype. No scorer, fit, decision override or rollout. */
import assert from "node:assert/strict";
import {IL_ACTION_FEATURE_NAMES, ilCandidateActionMetadata, ilActionFeatureVector} from "./sources/common/src/simulation/il_action_features";

type Cell={x:number,y:number};
type Row=Record<string,any>;
export const SCHEMA="barrel-public-native-catalog-features-v1";
const TYPES=new Set(["end_turn","wait_turn","defend_turn","select_attack_type","move_unit","melee_attack","range_attack","obstacle_attack","area_throw_attack","cast_spell"]);
const unitStats=["hp","alive","maxHp","exp","steps","initiative","armor","rangeArmor","shots","fly"];
const props=["level","faction","morale","luck","base_attack","attack_mod","attack_damage_min","attack_damage_max","attack_multiplier","attack_range","shot_distance","magic_resist","stack_power","movement_type","footprint_width","footprint_height"];
const legality=["hasMoved","isOnHourglass","hourglassIncludes","alreadyMadeTurn","alreadyHourglass","activeTimeDenial","hasUnactedTeammate","canWait"];
const abilities=["AI Driven","Double Punch","Rapid Charge","Through Shot","Time Denial","Range Null Field Aura","Armageddon","Regeneration","Deep Wounds Level 1","Deep Wounds Level 2","Deep Wounds Level 3"];
const groups=["count","hp","xp","shooters","casters","unacted","waitLegal","nearest","withinActorSteps","maxSteps"];
const extra=["isBefore","isCleanup","pathCost","destinationNearestEnemy","destinationNearestAlly","destinationChangeEnemyDistance","destinationThreatenedByUnacted","actorThreatenedByUnacted","destinationEdgeDistance","targetIsAlly","targetMissing","targetDistance","targetHp","targetXp","targetUnacted","targetShooter","targetCaster","targetWounded","targetArmor","targetRangeArmor","targetMagicResist","barrelPresent","barrelOwn","barrelEnemy","barrelDistance","ownBarrels","enemyBarrels","spellKnown","spellRemaining","spellPower","spellDuration","spellBuff","spellSelfAllowed","spellMinimumStack","spellStackSufficient"];
export const FEATURE_NAMES=[...IL_ACTION_FEATURE_NAMES,...unitStats.map(k=>"actor."+k),...props.map(k=>"actor.properties."+k),...legality.map(k=>"actor.turnLegality."+k),...abilities.map(k=>"actor.ability."+k),"lap","activeTimeDenial",...[1,2,3,4,5].map(k=>"map."+k),...groups.map(k=>"allies."+k),...groups.map(k=>"enemies."+k),...extra];
export interface PublicInput{actorId:string;lap:number;publicState:Row;before:Row[];cleanup:Row[];nativeCatalog:Row[];}
export interface Proposal{actions:Row[];key:string;isBefore:boolean;isCleanup:boolean;sourceKinds:string[];features:number[];blockedByPublicMask:boolean;}
const num=(value:unknown,defaultValue=0):number=>{if(value===undefined)return defaultValue;assert(typeof value==="number"&&Number.isFinite(value));return value;};
const bit=(value:unknown)=>value?1:0;
const distance=(a:readonly Cell[],b:readonly Cell[])=>a.length&&b.length?Math.min(...a.flatMap(x=>b.map(y=>Math.max(Math.abs(x.x-y.x),Math.abs(x.y-y.y))))):16;
const nearest=(cells:readonly Cell[],units:Row[])=>units.length?Math.min(...units.map(u=>distance(cells,u.cells))):16;
const sum=(xs:Row[],f:(x:Row)=>number)=>xs.reduce((a,x)=>a+f(x),0);
const sameCell=(a:Cell,b:Cell)=>a.x===b.x&&a.y===b.y;
const alive=(units:Row[])=>units.filter(u=>!u.dead&&u.alive>0).sort((a,b)=>{
 const key=(u:Row)=>JSON.stringify([u.team,u.name,[...u.cells].sort((l:Cell,r:Cell)=>l.x-r.x||l.y-r.y),u.hp,u.alive]);
 const ka=key(a),kb=key(b);return ka<kb?-1:ka>kb?1:0;
});
function ordered(value:any):any{
 if(Array.isArray(value))return value.map(ordered);
 if(value&&typeof value==="object")return Object.fromEntries(Object.keys(value).sort().filter(k=>value[k]!==undefined).map(k=>[k,ordered(value[k])]));
 return value;
}
export function actionKey(actions:readonly Row[]):string{
