"""Two local active fights, two modes and fresh-process epochs; no retries or extension."""
from pathlib import Path
import concurrent.futures,hashlib,json,os,queue,shutil,subprocess,threading,time
p=Path(__file__).resolve().parent;raw=(p/'registration.json').read_bytes();reg=json.loads(raw);seal=hashlib.sha256(raw).hexdigest()
old=p.parent/reg['sourceCapsule'];source=(old/'strength-registration.json').read_bytes()
assert hashlib.sha256(source).hexdigest()==reg['sourceRegistrationSha256']
for f in json.loads(source)['files']:assert hashlib.sha256((old/f['path']).read_bytes()).hexdigest()==f['sha256'],f['path']
for f in reg['files']:assert hashlib.sha256((p/f['path']).read_bytes()).hexdigest()==f['sha256'],f['path']
assert subprocess.check_output(['bun','--version'],text=True).strip()=='1.4.4'
cases=json.loads((p/'cases.json').read_text());assert len(cases)==14
out=p/'functional';out.mkdir();lock=threading.Lock();stop=threading.Event();processes=[];started=time.monotonic()
state={'complete':False,'stage':'starting','fights':0,'expectedFights':56,'epoch':0,'controllerPid':os.getpid(),
       'errors':[],'registrationSha256':seal,'absoluteDeadlineEpoch':reg['deadlineUnix']}
