   try:base=q.get_nowait()
   except queue.Empty:break
   modes=['baseline','observe']if(base['caseIndex']+epoch)%2==0 else['observe','baseline']
   for mode in modes:
    assert not stop.is_set()and time.time()<reg['deadlineUnix']
    job={**base,'epoch':epoch,'mode':mode,'jobId':f"{epoch}/{base['caseId']}"};proc=actors[mode]
    proc.stdin.write(json.dumps({'job':job,'registrationSha256':seal})+'\n');proc.stdin.flush()
    while True:
     line=proc.stdout.readline()
     if not line:raise RuntimeError(f'{mode} actor exited at '+job['jobId'])
     try:ack=json.loads(line)
     except json.JSONDecodeError:logs[mode].write(line);continue
     if isinstance(ack,dict)and ack.get('verified'):break
     logs[mode].write(line)
