  error=exc;halt(repr(exc));raise
 finally:
  for proc in actors.values():
   if proc.poll()is None:
    try:proc.stdin.close()
    except BrokenPipeError:pass
  for proc in actors.values():
   if stop.is_set()and proc.poll()is None:proc.terminate()
   result=proc.wait()
   if error is None and not stop.is_set():assert result==0
  for log in logs.values():log.close()
try:
 for epoch in range(2):
  state.update({'epoch':epoch,'stage':'fixed-cold-epoch'});save();q=queue.Queue()
  for case in cases:q.put(case)
  with concurrent.futures.ThreadPoolExecutor(max_workers=2)as pool:
   futures=[pool.submit(lane,epoch,i,q)for i in range(2)]
   while not all(f.done()for f in futures):
    for f in futures:
     if f.done()and f.exception()is not None:halt(repr(f.exception()))
    if not stop.is_set()and(shutil.disk_usage(p).free<reg['minimumFreeBytes']or sum(f.stat().st_size for f in out.rglob('*.gz'))>reg['maximumOutputBytes']):halt('Fixed disk floor or byte ceiling reached; preserve records')
    save();time.sleep(3)
   for f in futures:f.result()
  assert not stop.is_set()
