timer.daemon=True;timer.start()
def lane(epoch,index,q):
 actors={};logs={};error=None
 try:
  for mode in ['baseline','observe']:
   stem=f'e{epoch}-l{index}-{mode}';logs[mode]=(out/(stem+'.log')).open('x')
   proc=subprocess.Popen(['nice','-n','19','bun','--preload',str(p/'alias.ts'),str(p/'actor.ts'),str(out/(stem+'.jsonl.gz')),
    str(out/(stem+'-labels.jsonl.gz')),str(out/(stem+'-states.jsonl.gz')),mode],cwd=p,stdin=subprocess.PIPE,stdout=subprocess.PIPE,
    stderr=logs[mode],text=True,bufsize=1,env={**os.environ,'HOC_A19_CONTEXT_POLICY':'on'})
