const sha=(v:unknown)=>createHash("sha256").update(JSON.stringify(v)).digest("hex"),observations:any[]=[];
const analysis=JSON.parse(readFileSync(parent+"/analysis.json","utf8"));assert(analysis.passed);
for(const f of readdirSync(parent+"/functional").filter(f=>/^e0-.*-observe-labels\.jsonl\.gz$/.test(f))){
 const raw=readFileSync(parent+"/functional/"+f);assert.equal(createHash("sha256").update(raw).digest("hex"),analysis.rawFiles.find((r:any)=>r.path===f).sha256);
 for(const line of gunzipSync(raw).toString().trim().split("\n"))observations.push(...JSON.parse(line).labels);
}
assert.equal(observations.length,31);
function freeze(v:any):any{if(v&&typeof v==="object"){for(const x of Object.values(v))freeze(x);Object.freeze(v);}return v;}
function cleanProjection(o:any){return project(observationInput(o)).map(p=>({features:p.features,blocked:p.blockedByPublicMask}));}
function renamed(o:any){
 const ids=new Map(o.publicState.units.map((u:any,i:number)=>[u.id,"changed-id-"+i]));
 function visit(v:any):any{
  if(typeof v==="string")return ids.get(v)??v;
  if(Array.isArray(v))return v.map(visit);
  if(v&&typeof v==="object")return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,visit(x)]));
  return v;
 }
 const copy=visit(o);copy.publicState.units.reverse();copy.publicState.barrels.reverse();copy.publicState.units.forEach((u:any)=>u.cells.reverse());return copy;
}
describe("public candidate representation prototype",()=>{
 test("preflight examples have no family-seed overlap with the prospectively split main data",()=>{
  const pre=JSON.parse(readFileSync(cases+"/preflight-cases.json","utf8")),main=JSON.parse(readFileSync(cases+"/cases-all.json","utf8"));
  const seeds=new Set(main.map((r:any)=>r.seed));expect(pre.every((r:any)=>!seeds.has(r.seed))).toBe(true);
 });
 test("fixed controls keep original candidate plans and finite fixed-order public features",()=>{
  expect(new Set(FEATURE_NAMES).size).toBe(FEATURE_NAMES.length);
  let count=0,outside=0,blocked=0;
  for(const o of observations){const before=sha(o),joined=joinTeacher(freeze(structuredClone(o)));expect(sha(o)).toBe(before);
   outside+=+joined.outsideCatalog;blocked+=+joined.selectedBlockedByPublicMask;
   for(const proposal of joined.proposals){count++;expect(proposal.features.length).toBe(FEATURE_NAMES.length);expect(proposal.features.every(Number.isFinite)).toBe(true);}
   for(const c of o.rootRecords[0].shortlists[0].input)expect(joined.proposals.some((p:any)=>p.key===actionKey(c.actions))).toBe(true);
  }
  expect(outside).toBe(0);expect(blocked).toBe(0);
  console.log(JSON.stringify({reusedObservations:31,proposals:count,features:FEATURE_NAMES.length,outsideCatalog:outside,selectedBlocked:blocked,modelFitted:false}));
 });
 test("IDs, unit order and every later forecast/choice field cannot change X",()=>{
  for(const o of observations){
   const expected=cleanProjection(o);const copy=renamed(o);
   copy.chosenDecision=[{type:"defend_turn",unitId:copy.unitId}];copy.actualRawIncumbent=[];copy.actualTurn=999999;copy.ordinal=123;copy.rootCallOrdinal=33;copy.strategyActions=[];copy.score=0;copy.winner="red";copy.familyId="changed";copy.seed=33;
   for(const root of copy.rootRecords){root.queries=new Proxy([],{get(){throw new Error("Leaked later scoring query");}});root.innerChosen=[];root.shortlists[0].output=[];
    for(const c of root.shortlists[0].input){c.features=new Proxy({},{get(){throw new Error("Unallowlisted candidate features");}});c.shotFeatures={enemyDamage:1e9};}
    root.shortlists.push({input:[{kind:"wait",actions:[{type:"wait_turn",unitId:copy.unitId}]}],output:[]});
   }
   expect(cleanProjection(copy)).toEqual(expected);
  }
 });
 test("wait legality is a real public mask and never silently removes evidence",()=>{
  const o=structuredClone(observations.find(o=>o.rootRecords[0].shortlists[0].input.some((c:any)=>c.actions.some((a:any)=>a.type==="wait_turn"))));
  const actor=o.publicState.units.find((u:any)=>u.id===o.unitId);actor.turnLegality.canWait=false;
  const proposals=project(observationInput(o)),waits=proposals.filter(p=>p.actions.some(a=>a.type==="wait_turn"));expect(waits.length).toBeGreaterThan(0);expect(waits.every(p=>p.blockedByPublicMask)).toBe(true);
 });
 test("zero-charge and insufficient-stack spell proposals are retained and blocked",()=>{
  const o=structuredClone(observations.find(o=>o.rootRecords[0].shortlists[0].input.some((c:any)=>c.actions.some((a:any)=>a.type==="cast_spell"))));
  const actor=o.publicState.units.find((u:any)=>u.id===o.unitId);for(const spell of actor.spells)spell.remaining=0;
  const proposals=project(observationInput(o)),spells=proposals.filter(p=>p.actions.some(a=>a.type==="cast_spell"));expect(spells.length).toBeGreaterThan(0);expect(spells.every(p=>p.blockedByPublicMask)).toBe(true);
  for(const spell of actor.spells){spell.remaining=1;spell.properties.minimal_caster_stack_power=actor.properties.stack_power+1;}
  expect(project(observationInput(o)).filter(p=>p.actions.some(a=>a.type==="cast_spell")).every(p=>p.blockedByPublicMask)).toBe(true);
 });
 test("exact command keys normalize footprint order and absent false flags while retaining the full path",()=>{
  const a=[{type:"move_unit",unitId:"a",path:[{x:1,y:2},{x:2,y:3}],targetCells:[{x:2,y:3},{x:1,y:3}]}];
  const b=structuredClone(a)as any;b[0].targetCells.reverse();b[0].hasLavaCell=false;b[0].hasWaterCell=false;expect(actionKey(a)).toBe(actionKey(b));
  b[0].path=[{x:1,y:2},{x:2,y:2},{x:2,y:3}];expect(actionKey(a)).not.toBe(actionKey(b));
  expect(()=>actionKey([{type:"unknown_action"}])).toThrow();
 });
 test("feature projection never draws randomness or changes deterministic UUID state",()=>{
  const before=captureDeterministicRandomState(),random=Math.random;Math.random=()=>{throw new Error("Feature extraction drew randomness");};
  try{for(const o of observations)project(observationInput(o));}finally{Math.random=random;}
  expect(captureDeterministicRandomState()).toEqual(before);
 });
 test("outside-catalog actual choices are explicitly retained as missing targets",()=>{
  const copy=structuredClone(observations[0]);copy.chosenDecision=[{type:"move_unit",unitId:copy.unitId,path:[{x:99,y:99}],targetCells:[{x:99,y:99}]}];
  const joined=joinTeacher(copy);expect(joined.target).toBe(-1);expect(joined.outsideCatalog).toBe(true);expect(joined.proposals.length).toBeGreaterThan(0);
 });
});

