/** Untrained, inactive extension. Only static metadata from the first native catalog is admissible. */
import assert from "node:assert/strict";
import {FEATURE_NAMES as BASE_FEATURE_NAMES,project as baseProject,actionKey,observationInput,type PublicInput} from "../barrel-public-action-representation-v1-20261118/representation";
import {IL_SHOT_FEATURE_NAMES} from "../barrel-catalog-teacher-v11-20261118/sources/common/src/simulation/il_action_features";
export {actionKey,observationInput};
export const SCHEMA="barrel-public-native-static-catalog-features-v2";
export const STATIC_NAMES=["moraleDelta","luckDelta","enemiesNotYetActedFrac","alliesNotYetActedFrac","lap","hourglassSpent","spendsRangeShot","spendsSpellCharge","burnsResurrectionCharge","expectedDamage","expectedKill"]as const;
export const SPELL_NAMES=["level","spell_target_type","power_type","multiplier_type","element","self_debuff_applies","is_giftable","maximum_gift_level"]as const;
export const FEATURE_NAMES=[...BASE_FEATURE_NAMES,"hasNativeStaticMetadata",...STATIC_NAMES.map(k=>"native."+k),"hasNativeShotMetadata",...IL_SHOT_FEATURE_NAMES.map(k=>"native.shot."+k),...SPELL_NAMES.map(k=>"spell."+k),"spellTargetOutsideActiveRoster","spellTargetDeadInRoster"];
const value=(x:unknown)=>{if(x===undefined)return 0;if(typeof x==="boolean")return+x;assert(typeof x==="number"&&Number.isFinite(x));return x;};
export function project(input:PublicInput){
 const actor=input.publicState.units.find((u:any)=>u.id===input.actorId);assert(actor);
 const records=new Map<string,any>();for(const c of input.nativeCatalog){const key=actionKey(c.actions);if(!records.has(key))records.set(key,c);}
 return baseProject(input).map(p=>{
  const native=records.get(p.key),staticFeatures=native?.features,shot=native?.shotFeatures,spellAction=p.actions.find(a=>a.type==="cast_spell"),attack=p.actions.find(a=>a.type==="melee_attack"||a.type==="range_attack"),
   spell=spellAction?actor.spells.find((s:any)=>s.name===spellAction.spellName):undefined,recipient=spellAction?.targetId?input.publicState.units.find((u:any)=>u.id===spellAction.targetId):undefined,
   attackTarget=attack?.targetId?input.publicState.units.find((u:any)=>u.id===attack.targetId):undefined;
  // Missing/dead spell recipients may be legal graveyard resurrection targets. They are unknown here,
  // not proven illegal. A later policy must abstain for this incomplete public recipient representation.
  const missingRecipient=!!spellAction?.targetId&&!recipient,deadRecipient=!!recipient?.dead;
  const blocked=p.actions.some(a=>a.type==="wait_turn")&&!actor.turnLegality.canWait||!!attack?.targetId&&(!attackTarget||attackTarget.dead)||!!spellAction&&(!spell||spell.remaining<=0);
  const features=[...p.features,+!!staticFeatures,...STATIC_NAMES.map(k=>value(staticFeatures?.[k])),+!!shot,...IL_SHOT_FEATURE_NAMES.map(k=>value(shot?.[k])),...SPELL_NAMES.map(k=>value(spell?.properties[k])),+missingRecipient,+deadRecipient];
  assert.equal(features.length,FEATURE_NAMES.length);assert(features.every(Number.isFinite));
  return{...p,features,blockedByPublicMask:!!blocked,requiresUnavailablePublicRecipient:missingRecipient||deadRecipient};
 });
}
export function joinTeacher(o:any){
 const input=observationInput(o),proposals=project(input),key=actionKey(o.chosenDecision),target=proposals.findIndex(p=>p.key===key);
 return{schema:SCHEMA,proposals,target,outsideCatalog:target<0,selectedBlockedByPublicMask:target>=0&&proposals[target].blockedByPublicMask,
  requiresPublicRecipientAbstention:proposals.some(p=>p.requiresUnavailablePublicRecipient)};
}

import {test,expect} from "bun:test";
import {readFileSync,readdirSync} from "node:fs";
import {gunzipSync} from "node:zlib";
import {FEATURE_NAMES,STATIC_NAMES,SPELL_NAMES,project,joinTeacher,observationInput,actionKey} from "./representation";
const p=import.meta.dir+"/../barrel-legal-catalog-observer-v2-20261118/functional",observations:any[]=[];
for(const f of readdirSync(p).filter(f=>/^e0-.*-observe-labels\.jsonl\.gz$/.test(f)))for(const line of gunzipSync(readFileSync(p+"/"+f)).toString().trim().split("\n"))observations.push(...JSON.parse(line).labels);
expect(observations.length).toBe(31);
test("all known controls keep finite public rows and their observed action labels",()=>{
 expect(new Set(FEATURE_NAMES).size).toBe(FEATURE_NAMES.length);let count=0;
 for(const o of observations){const j=joinTeacher(o);expect(j.outsideCatalog).toBe(false);expect(j.selectedBlockedByPublicMask).toBe(false);for(const p of j.proposals){count++;expect(p.features.length).toBe(FEATURE_NAMES.length);expect(p.features.every(Number.isFinite)).toBe(true);}}
 console.log(JSON.stringify({observations:31,proposals:count,features:FEATURE_NAMES.length,staticFields:STATIC_NAMES.length,spellFields:SPELL_NAMES.length,modelFitted:false}));
});
test("static immediate damage is admitted explicitly while later rollout scores cannot enter X",()=>{
 const o=structuredClone(observations[0]),before=project(observationInput(o));o.rootRecords[0].queries=new Proxy([],{get(){throw new Error("Leaked forecast evidence");}});o.chosenDecision=[];o.score=0;o.seed=17;
 expect(project(observationInput(o))).toEqual(before);
 const input=observationInput(o),first=input.nativeCatalog[0],key=actionKey(first.actions);first.features.expectedDamage+=7;
 const changed=project(input),index=FEATURE_NAMES.indexOf("native.expectedDamage");expect(changed.find(p=>p.key===key)!.features[index]).toBe(before.find(p=>p.key===key)!.features[index]+7);
});
test("a graveyard spell target is unknown public input rather than a false illegal-target certificate",()=>{
 const input=structuredClone(observationInput(observations[0])),actor=input.publicState.units.find((u:any)=>u.id===input.actorId);
 actor.spells=actor.spells.filter((s:any)=>s.name!=="Resurrection");
 actor.spells.push({name:"Resurrection",remaining:1,properties:{name:"Resurrection",power_type:5,spell_target_type:2,multiplier_type:2,power:1,laps:0,level:4,self_cast_allowed:true,minimal_caster_stack_power:0}});
 const actions=[{type:"cast_spell",casterId:input.actorId,spellName:"Resurrection",targetId:"public-graveyard-corpse"}];input.nativeCatalog.push({kind:"spell",actions,features:Object.fromEntries(STATIC_NAMES.map(k=>[k,0]))});
 const p=project(input).find(p=>p.key===actionKey(actions))!;expect(p.blockedByPublicMask).toBe(false);expect(p.requiresUnavailablePublicRecipient).toBe(true);expect(p.features[FEATURE_NAMES.indexOf("spell.power_type")]).toBe(5);
 actor.spells.at(-1).remaining=0;expect(project(input).find(candidate=>candidate.key===actionKey(actions))!.blockedByPublicMask).toBe(true);
});
test("a nonexistent attack target remains a definite invalid target",()=>{
 const input=structuredClone(observationInput(observations[0]));const actions=[{type:"melee_attack",attackerId:input.actorId,targetId:"missing-alive-target",attackFrom:{x:0,y:0}}];input.nativeCatalog.push({kind:"melee",actions});
 const p=project(input).find(p=>p.key===actionKey(actions))!;expect(p.blockedByPublicMask).toBe(true);expect(p.requiresUnavailablePublicRecipient).toBe(false);
});
test("spell mechanics distinguish otherwise identical public casts",()=>{
 const input=structuredClone(observationInput(observations[0])),actor=input.publicState.units.find((u:any)=>u.id===input.actorId);const actions=[{type:"cast_spell",casterId:input.actorId,spellName:"Synthetic public spell"}];
 actor.spells.push({name:"Synthetic public spell",remaining:1,properties:{name:"Synthetic public spell",power_type:1,multiplier_type:1,spell_target_type:4,element:0,level:1}});input.nativeCatalog.push({kind:"spell",actions});
 const a=project(input).find(p=>p.key===actionKey(actions))!.features;actor.spells.at(-1).properties.power_type=5;const b=project(input).find(p=>p.key===actionKey(actions))!.features;
 expect(a[FEATURE_NAMES.indexOf("spell.power_type")]).toBe(1);expect(b[FEATURE_NAMES.indexOf("spell.power_type")]).toBe(5);
});
